{"explanation":"For a normal distribution, about 68% of values lie within 1 standard deviation of the mean, 95% within 2, and 99.7% within 3. These percentages are areas under the bell curve, centered symmetrically around the mean μ. Move the slider to compare the three intervals; σ denotes the standard deviation.","manimCode":"const title = new Text({ text: 'The 68–95–99.7 rule', fontSize: 34, color: WHITE });
title.moveTo([-1, 3.15, 0]);
const subtitle = new Text({ text: 'Area under the curve = probability', fontSize: 22, color: GRAY });
subtitle.moveTo([-1, 2.55, 0]);

const ax = new Axes({
  xRange: [-4, 4, 1],
  yRange: [-0.05, 0.45, 0.1],
  xLength: 10,
  yLength: 4,
  tips: false
});
ax.moveTo([0, -0.35, 0]);
const density = x => Math.exp(-x * x / 2) / Math.sqrt(2 * Math.PI);
const bell = ax.plot(density, { color: WHITE, numSamples: 500 });
bell.setStrokeWidth(3);

const tickGroup = new VGroup();
const tickNames = ['μ − 3σ', 'μ − 2σ', 'μ − σ', 'μ', 'μ + σ', 'μ + 2σ', 'μ + 3σ'];
for (let j = -3; j <= 3; j++) {
  const tickLabel = new Text({ text: tickNames[j + 3], fontSize: 17, color: GRAY });
  tickLabel.moveTo(ax.coordsToPoint(j, 0));
  tickLabel.shift([0, -0.3, 0]);
  tickGroup.add(tickLabel);
}

const meanGuide = new Line({ start: ax.coordsToPoint(0, 0), end: ax.coordsToPoint(0, density(0)), color: GRAY });
meanGuide.setStrokeWidth(1);
await scene.play(new AnimationGroup([new Write(title), new FadeIn(subtitle), new Create(ax)]));
scene.add(tickGroup, meanGuide);
await scene.play(new Create(bell));

let selected = 1;
let shadedArea;
let boundaryGroup;
let percentageLabel;
let intervalLabel;
const percentages = ['68%', '95%', '99.7%'];
const palette = [BLUE, TEAL, PURPLE];

function showInterval(n) {
  selected = Math.max(1, Math.min(3, Math.round(n)));
  if (shadedArea) scene.remove(shadedArea);
  if (boundaryGroup) scene.remove(boundaryGroup);
  if (percentageLabel) scene.remove(percentageLabel);
  if (intervalLabel) scene.remove(intervalLabel);
  const hue = palette[selected - 1];
  shadedArea = ax.getArea(bell, [-selected, selected], { color: hue, opacity: 0.45 });
  boundaryGroup = new VGroup();
  for (const endpoint of [-selected, selected]) {
    const boundary = new Line({
      start: ax.coordsToPoint(endpoint, 0),
      end: ax.coordsToPoint(endpoint, density(endpoint)),
      color: hue
    });
    boundary.setStrokeWidth(4);
    boundaryGroup.add(boundary);
  }
  percentageLabel = new Text({ text: '≈ ' + percentages[selected - 1], fontSize: 34, color: hue });
  percentageLabel.moveTo([0, 1.8, 0]);
  intervalLabel = new Text({
    text: 'Within ' + selected + ' standard deviation' + (selected === 1 ? '' : 's') + ' of μ',
    fontSize: 23,
    color: hue
  });
  intervalLabel.moveTo([0, -3.1, 0]);
  scene.add(shadedArea);
  // Keep the bell outline and mean marker above the translucent area.
  scene.remove(bell, meanGuide);
  scene.add(bell, meanGuide, boundaryGroup, percentageLabel, intervalLabel);
}

showInterval(1);
await scene.wait(1.2);
showInterval(2);
await scene.wait(1.2);
showInterval(3);
await scene.wait(1.2);
showInterval(1);

const controls = new Controls(scene, { position: 'top-right', width: 220, theme: 'dark' });
controls.addSlider({
  label: 'Standard deviations (σ)',
  min: 1,
  max: 3,
  step: 1,
  value: 1,
  onChange: value => showInterval(value)
});
await scene.wait(999999);"}

